import { GUID } from '@servicenow/sdk-build-core'
import { Connector, type OAuthCredential } from '../../src'

type FetchArgs = [string, Record<string, string>]

describe('Connector.getScopeInfo Test Suite', () => {
    const scopeId = GUID()
    const scope = 'xsn_test_scope'
    const response = [{ sys_id: scopeId, sys_class_name: 'sys_app', active: 'true ' }]

    let connector: Connector

    const credential: OAuthCredential = {
        type: 'oauth',
        token: GUID(),
        instanceUrl: new URL('/testing', 'http://localhost:8080'),
    }

    beforeEach(() => {
        connector = new Connector(credential)
        jest.spyOn(connector as any, 'fetchApiNowTable').mockImplementation(async () => response)
    })

    it('should include the scopeId when passed', async () => {
        await connector.getScopeInfo(scope, scopeId)
        const params = ((connector as any).fetchApiNowTable.mock.calls[0] as FetchArgs)[1]

        expect(params['sysparm_query']).toBe(`scope=${scope}^sys_id=${scopeId}`)
    })

    it('should fall back to just the scope', async () => {
        await connector.getScopeInfo(scope, '')
        const params = ((connector as any).fetchApiNowTable.mock.calls[0] as FetchArgs)[1]

        expect(params['sysparm_query']).toBe(`scope=${scope}`)
    })
})
